type Document = { id: string; title: string };
type Snapshot = { documents: readonly Document[]; pending: boolean; error: string | null };
declare function useLiveDocuments(): Snapshot;
export function Explorer() {
  const { documents, pending, error } = useLiveDocuments();
  if (pending) return <p role="status">Loading</p>;
  if (error) return <p role="alert">{error}</p>;
  if (documents.length === 0) return <p>No documents</p>;
  return <section><h2>{documents.length}</h2><ul>{documents.map(document => <li key={document.id}>{document.title}</li>)}</ul></section>;
}

type Result = { id: string; label: string };
declare function useSearchResults(): { results: readonly Result[]; pending: boolean; error: string | null };
function ResultsView({ results }: { results: readonly Result[] }) {
  return <ul>{results.map(result => <li key={result.id}>{result.label}</li>)}</ul>;
}
export function SearchResults() {
  const { results, pending, error } = useSearchResults();
  if (pending) return <p role="status">Searching</p>;
  if (error) return <p role="alert">{error}</p>;
  return <ResultsView results={results} />;
}

import { createContext, useContext, useState, type ReactNode } from 'react';
type Entry = { id: string; title: string };
type Model = { entries: readonly Entry[]; pending: boolean; error: string | null; add: (title: string) => Promise<Entry> };
declare function useBoardModel(boardId: string): Model;
const BoardContext = createContext<Model | null>(null);
function useBoard() { const value = useContext(BoardContext); if (!value) throw new Error('BoardProvider is required'); return value; }
function Row({ entry }: { entry: Entry }) { const [draft, setDraft] = useState(entry.title); return <li><input value={draft} onChange={event => setDraft(event.target.value)} /></li>; }
function Header() { const board = useBoard(); return <header>{board.entries.length}</header>; }
function List() { const board = useBoard(); return <ul>{board.entries.map(entry => <Row key={entry.id} entry={entry} />)}</ul>; }
export function BoardProvider({ boardId, children }: { boardId: string; children: ReactNode }) { const model = useBoardModel(boardId); return <BoardContext.Provider value={model}>{children}</BoardContext.Provider>; }
export function Board({ boardId }: { boardId: string }) { return <BoardProvider boardId={boardId}><Header /><List /></BoardProvider>; }

import { createContext, useContext, useState, type ReactNode } from 'react';
type Document = { id: string; title: string };
type Model = { documents: readonly Document[]; add: (title: string) => Promise<Document>; pending: boolean; error: string | null };
declare function useDocumentsModel(): Model;
const Context = createContext<Model | null>(null);
function useDocuments() { const value = useContext(Context); if (!value) throw new Error('DocumentsProvider is required'); return value; }
function DocumentRow({ document }: { document: Document }) { const [draft, setDraft] = useState(document.title); return <li><input value={draft} onChange={event => setDraft(event.target.value)} /></li>; }
function Header() { const { add } = useDocuments(); return <header><button onClick={() => { void add('Untitled').catch(() => {}); }}>Add</button></header>; }
function List() { const { documents } = useDocuments(); return <ul>{documents.map(document => <DocumentRow key={document.id} document={document} />)}</ul>; }
export function DocumentsProvider({ children }: { children: ReactNode }) { const model = useDocumentsModel(); return <Context.Provider value={model}>{children}</Context.Provider>; }
export function Documents() { const { pending, error } = useDocuments(); return <DocumentsProvider><Header /><List />{pending && <p role="status">Saving</p>}{error && <p role="alert">{error}</p>}</DocumentsProvider>; }

import type { ReactNode } from 'react';
type Order = { id: string; title: string; status: string; amount: string };
type Props = { order: Order; dense?: boolean; status?: ReactNode; statusLink?: ReactNode; statusFirst?: boolean; showAmount?: boolean };
export function OrderRow({ order, dense = false, status, statusLink, statusFirst = true, showAmount = true }: Props) {
  const statusPart = <span>{status ?? order.status}{statusLink}</span>;
  const amountPart = showAmount && <span>{order.amount}</span>;
  return <article data-density={dense ? 'compact' : 'normal'}><h3>{order.title}</h3>{statusFirst ? statusPart : amountPart}{statusFirst ? amountPart : statusPart}</article>;
}
